          phase = 'exit';
          settle = 0;
        }

        if (phase === 'exit') {
          target = { x: gate.x + 0.25, y: gate.y, z: gate.z };
          if (p.x > gate.x + 0.16 && vx > -0.05) {
            activeGate = obs.gateIndex;
            if (activeGate < 3) {
